+fn section_mode_param(records: &[Record]) -> Option<String> {
+    records.iter().find_map(|r| match r {
+        Record::Param { name, value } if name == "SectionMode" => match value {
+            Value::String(s) => Some(s.clone()),
+            other => Some(other.to_string()),
+        },
+        _ => None,
+    })
+}
