+/// One segment handed to [`solve_g93_segment`].
+#[derive(Clone, Copy, Debug, PartialEq)]
+pub struct G93SegmentInput {
+    pub kind: MoveKind,
+    /// Part-space start tool tip (mm, or linear units when passed to [`solve_g93_segment_in_units`]).
+    pub tip_from: [f64; 3],
